// Auto-generated: the two one-shot SFX inlined as base64 data URIs so they can be
// fetched + decoded by the Web Audio API even when the page is opened via file://
// (where fetch/XHR of a plain file path is blocked). Used by script.js for
// glitch-free, zero-latency cover-flip / page-flip sounds.
// Format: Ogg/Opus (was MP3) — decodeAudioData handles Opus in Chrome, Edge,
// Firefox and Safari 15+, the same browsers that support the WebM/VP9 pages.
window.SFX_DATA = {
  cover: "data:audio/ogg;base64,",
  flip: "data:audio/ogg;base64,"
};
